products.css:
/* ===== Buttons Css ===== */
.error-content .primary-btn {
  background: var(--primary);
  color: var(--white);
  box-shadow: var(--shadow-2);
}
.error-content .active.primary-btn, .error-content .primary-btn:hover, .error-content .primary-btn:focus {
  background: var(--primary-dark);
  color: var(--white);
  box-shadow: var(--shadow-4);
}
.error-content .deactive.primary-btn {
  background: var(--gray-4);
  color: var(--dark-3);
  pointer-events: none;
}

/*===== ERROR ONE Style =====*/
.error-content {
  padding-top: 120px;
  padding-bottom: 120px;
}
.error-content .error-404 {
  font-size: 98px;
  font-weight: 600;
  color: var(--black);
  line-height: 90px;
}
.error-content .sub-title {
  font-size: 24px;
  font-weight: 700;
  color: var(--black);
  margin-top: 16px;
}
.error-content .text {
  font-size: 16px;
  line-height: 24px;
  color: var(--dark-3);
  margin-top: 8px;
}
.error-content .error-form {
  max-width: 410px;
  position: relative;
  margin: 0 auto;
  margin-top: 40px;
  position: relative;
}
.error-content .error-form i {
  position: absolute;
  top: 12px;
  left: 20px;
  font-size: 24px;
  color: var(--primary);
}
.error-content .error-form input {
  width: 100%;
  height: 46px;
  padding-left: 60px;
  padding-right: 30px;
  border-radius: 50px;
  border: 2px solid var(--gray-4);
  font-size: 16px;
  font-weight: 600;
  color: var(--dark-3);
}
.error-content .error-form input:focus {
  border-color: var(--primary);
}
.error-content .error-btn {
  position: absolute;
  top: 0;
  right: 0;
}
@media (max-width: 767px) {
  .error-content .error-btn {
    position: relative;
    width: 100%;
    margin-top: 8px;
  }
}
@media (max-width: 767px) {
  .error-content .primary-btn {
    width: 100%;
  }
}

/*===== ERROR STYLE 2 =====*/
.primary-btn { background: var(--secondary); color: var(--white); box-shadow: var(--shadow-2); padding: 12px 26px; border-radius: 6px; font-weight: 600; border: none; }
.primary-btn:hover { background: var(--secondary-dark); color: var(--white); box-shadow: var(--shadow-4); }
.outline-btn { border: 1.5px solid var(--secondary); color: var(--secondary); padding: 11px 24px; border-radius: 6px; font-weight: 600; background: transparent; }
.outline-btn:hover { background: var(--secondary); color: var(--white); }
.errors-style-3 { background: var(--light-2); padding: 70px 0; }
.errors-style-3 .section-box { background: var(--white); border: 1px solid var(--gray-4); border-radius: 16px; padding: 42px 34px; box-shadow: var(--shadow-2); }
.errors-style-3 .tag-label { color: var(--secondary); font-size: 13px; font-weight: 700; letter-spacing: .06em; }
.errors-style-3 h2, .errors-style-3 h5 { color: var(--black); }
.errors-style-3 p { color: var(--dark-2); }
.errors-style-3 .mini-card { padding: 24px; border-radius: 12px; background: var(--light-2); border: 1px solid var(--gray-4); height: 100%; }
.errors-style-3 .mini-card i { color: var(--secondary); }

